using FluentValidation;using Microsoft.EntityFrameworkCore;using Npgsql;using SchoolERP.Application.Exceptions;using SchoolERP.Domain.Exceptions;
namespace SchoolERP.Api.ErrorHandling;
public sealed class ApiExceptionMapper:IExceptionMapper
{
 public ApiErrorDescriptor Map(Exception e)
 {
  if(e is ValidationException v)return new(400,ErrorCodes.ValidationFailed,"One or more validation errors occurred.",v.Errors.GroupBy(x=>Camel(x.PropertyName)).ToDictionary(g=>g.Key,g=>g.Select(x=>x.ErrorMessage).Distinct().ToArray()),LogLevel.Information);
  if(e is ResourceNotFoundException)return new(404,ResourceCode(e.Message),SafeNotFound(e.Message),null,LogLevel.Information);
  if(e is TenantContextMissingException)return new(403,ErrorCodes.TenantContextMissing,"Tenant context is required for this operation.",null,LogLevel.Warning);
  if(e is TenantMismatchException)return new(404,ErrorCodes.NotFound,"The requested resource was not found.",null,LogLevel.Warning);
  if(e is UnauthorizedAccessException)return new(403,ErrorCodes.PermissionDenied,"You do not have permission to perform this action.",null,LogLevel.Warning);
  if(e is DbUpdateConcurrencyException or ConcurrencyConflictException)return new(409,ErrorCodes.Concurrency,"The resource was modified by another request. Refresh and try again.",null,LogLevel.Warning);
  if(e is TimeoutException)return new(503,ErrorCodes.OperationTimeout,"Service is temporarily unavailable.",null,LogLevel.Error,false);
  if(e is DbUpdateException d)return Database(d);
  if(e is NpgsqlException)return new(503,ErrorCodes.DatabaseUnavailable,"Database temporarily unavailable.",null,LogLevel.Error,false);
  if(IsConflict(e))return new(409,StableCode(e),SafeMessage(e),null,LogLevel.Warning);
  if(e is DomainException)return new(400,StableCode(e),SafeMessage(e),null,LogLevel.Information);
  return new(500,ErrorCodes.Unexpected,"An unexpected error occurred.",null,LogLevel.Error,false);
 }
 private static ApiErrorDescriptor Database(DbUpdateException e){if(e.InnerException is PostgresException p){if(p.SqlState==PostgresErrorCodes.UniqueViolation)return new(409,ConstraintCodes.TryGetValue(p.ConstraintName??"",out var c)?c:"Common.AlreadyExists","A resource with the same unique value already exists.",null,LogLevel.Warning);if(p.SqlState==PostgresErrorCodes.ForeignKeyViolation)return new(409,"Persistence.RelationshipConflict","The operation conflicts with an existing relationship.",null,LogLevel.Warning);if(p.SqlState==PostgresErrorCodes.CheckViolation)return new(400,"Validation.ConstraintFailed","One or more values are invalid.",null,LogLevel.Information);}return new(503,ErrorCodes.DatabaseUnavailable,"Database temporarily unavailable.",null,LogLevel.Error,false);}
 private static bool IsConflict(Exception e)=>e is SchoolSelectionRequiredException or SchoolArchivedReadOnlyException or CampusArchivedReadOnlyException or MainCampusCannotBeSuspendedException or MainCampusCannotBeArchivedException or SchoolClassCodeConflictException or SchoolClassParentUnavailableException or ClassSectionCodeConflictException or ClassSectionNameConflictException or ClassSectionParentUnavailableException or SubjectCodeConflictException or SubjectNameConflictException or SubjectParentUnavailableException or SubjectHasClassAssignmentsException or ClassSubjectMismatchException or DepartmentCodeConflictException or DepartmentNameConflictException or DepartmentCampusUnavailableException or HouseCodeConflictException or HouseNameConflictException or InvalidHouseStatusTransitionException or HouseArchivedReadOnlyException or SchoolCalendarCodeConflictException or SchoolCalendarParentUnavailableException or SchoolCalendarInvalidTransitionException or SchoolCalendarArchivedReadOnlyException or TenantSlugConflictException or SchoolCodeConflictException or CampusCodeConflictException or MainCampusConflictException or ParentNotOperationalException or AcademicYearCodeConflictException or AcademicYearOverlapException or CurrentAcademicYearConflictException or TenantNotOperationalException or InvalidTenantStatusTransitionException or InvalidSchoolStatusTransitionException or InvalidCampusStatusTransitionException or InvalidAcademicYearStatusTransitionException;
 private static string StableCode(Exception e){var m=e.Message;if(m.Length<=100&&m.Contains('.')&&!m.Contains(' '))return m;return e switch{TenantSlugConflictException=>"Tenant.SlugAlreadyExists",SchoolCodeConflictException=>"School.CodeAlreadyExists",CampusCodeConflictException=>"Campus.CodeAlreadyExists",AcademicYearCodeConflictException=>"AcademicYear.CodeAlreadyExists",AcademicYearOverlapException=>"AcademicYear.DateOverlap",_=>"Business.RuleViolation"};}
 private static string SafeMessage(Exception e){var c=StableCode(e);return c switch{"Tenant.SlugAlreadyExists"=>"A tenant with this slug already exists.","School.CodeAlreadyExists"=>"A school with this code already exists.","Campus.CodeAlreadyExists"=>"A campus with this code already exists.","AcademicYear.DateOverlap"=>"Academic year overlaps with an existing academic year.",_ when c!="Business.RuleViolation"=>Words(c),_=>"The requested operation violates a business rule."};}
 private static string ResourceCode(string m){var n=m.Split(' ',StringSplitOptions.RemoveEmptyEntries).FirstOrDefault()??"Common";return n.Equals("Academic",StringComparison.OrdinalIgnoreCase)?"AcademicYear.NotFound":n+".NotFound";}
 private static string SafeNotFound(string m)=>m.Replace(" was not found."," not found.",StringComparison.OrdinalIgnoreCase);
 private static string Words(string code)=>code.Replace("."," ")+".";private static string Camel(string x)=>string.IsNullOrEmpty(x)?string.Empty:char.ToLowerInvariant(x[0])+x[1..];
 private static readonly Dictionary<string,string> ConstraintCodes=new(StringComparer.Ordinal){["ux_schools_tenant_id_code"]="School.CodeAlreadyExists",["ux_campuses_school_id_code"]="Campus.CodeAlreadyExists",["ux_academic_years_school_id_code"]="AcademicYear.CodeAlreadyExists",["ux_school_classes_school_year_code"]="Class.CodeAlreadyExists",["ux_class_sections_class_code"]="Section.CodeAlreadyExists",["ux_subjects_school_year_code"]="Subject.CodeAlreadyExists",["ux_departments_school_code"]="Department.CodeAlreadyExists",["ux_houses_school_code"]="House.CodeAlreadyExists",["ux_calendar_school_code"]="Calendar.CodeAlreadyExists"};
}
